import { useState, useCallback, KeyboardEvent, ChangeEvent } from 'react';

interface ArticleTagInputProps {
  label?: string;
  placeholder?: string;
  initialTags?: string[];
  maxTags?: number;
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagInput({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  initialTags = [],
  maxTags,
  onChange,
}: ArticleTagInputProps) {
  const [tags, setTags] = useState<string[]>(initialTags);
  const [inputValue, setInputValue] = useState('');

  const commitTags = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange]
  );

  const addTag = useCallback(
    (rawTag: string) => {
      const cleanTag = rawTag.trim();
      if (!cleanTag) return;
      if (tags.includes(cleanTag)) return;
      if (maxTags !== undefined && tags.length >= maxTags) return;
      commitTags([...tags, cleanTag]);
      setInputValue('');
    },
    [tags, maxTags, commitTags]
  );

  const removeTag = useCallback(
    (tagToRemove: string) => {
      commitTags(tags.filter((tag) => tag !== tagToRemove));
    },
    [tags, commitTags]
  );

  const handleInputChange = (event: ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value;
    if (value.endsWith(',')) {
      addTag(value.slice(0, -1));
      return;
    }
    setInputValue(value);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTag(inputValue);
      return;
    }
    if (event.key === 'Backspace' && inputValue === '' && tags.length > 0) {
      event.preventDefault();
      removeTag(tags[tags.length - 1]);
    }
  };

  const atLimit = maxTags !== undefined && tags.length >= maxTags;

  return (
    <div className="jx-field">
      <label className="jx-label" htmlFor="article-tag-input">
        {label}
      </label>

      <input
        id="article-tag-input"
        className="jx-input"
        type="text"
        value={inputValue}
        placeholder={atLimit ? 'Достигнут лимит тегов' : placeholder}
        onChange={handleInputChange}
        onKeyDown={handleKeyDown}
        disabled={atLimit}
        style={{ borderRadius: 'var(--jx-radius)' }}
      />

      {tags.length > 0 && (
        <ul
          className="jx-chip-list"
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: 'var(--jx-space-xs, 6px)',
            marginTop: 'var(--jx-space-sm, 8px)',
            listStyle: 'none',
            padding: 0,
          }}
        >
          {tags.map((tag) => (
            <li key={tag} className="jx-chip">
              <span className="jx-chip__label">{tag}</span>
              <button
                type="button"
                className="jx-chip__remove"
                aria-label={`Удалить тег ${tag}`}
                onClick={() => removeTag(tag)}
              >
                ×
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

